using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class Cave202Backface{
 [Serializable]class Result{public bool pass;public float before,after;public int litPixels;public string condition;}
 public static void Run(){string root=Path.GetFullPath(Path.Combine(Application.dataPath,"..")),output=Path.Combine(root,"Evidence202");try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);GraphicsSettings.defaultRenderPipeline=QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;Shader.SetGlobalVector("_TDPineWind",new Vector4(.8f,.6f,.7f,1.25f));
  var cam=new GameObject("below-leaf offscreen").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.fieldOfView=38;var light=new GameObject("below-leaf point").AddComponent<Light>();light.type=LightType.Point;light.intensity=3;light.range=5;light.color=new Color(1,.7f,.4f);float[] mean=new float[2];int lit=0;
  for(int stage=0;stage<2;stage++){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot "+(stage==0?"17":"23")+"/cnd001.prefab");var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var renderer=o.GetComponent<Renderer>();var material=new Material(renderer.sharedMaterial);material.SetFloat("_Cull",(float)CullMode.Front);renderer.sharedMaterial=material;var target=renderer.bounds.center;cam.transform.position=target+new Vector3(.3f,-1,.6f);cam.transform.LookAt(target);light.transform.position=target+new Vector3(.4f,-1,.3f);var im=Shared117Review.Image(cam,480,360);var pixels=im.GetPixels();mean[stage]=pixels.Average(c=>(c.r+c.g+c.b)/3);if(stage==1)lit=pixels.Count(c=>c.maxColorComponent>.01f);File.WriteAllBytes(Path.Combine(output,"leaf-actual-backface-"+stage+".png"),im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);UnityEngine.Object.DestroyImmediate(o);UnityEngine.Object.DestroyImmediate(material);}
  bool pass=mean[0]==0&&mean[1]>.0001f&&lit>50;File.WriteAllText(Path.Combine(output,"actual-backface.json"),JsonUtility.ToJson(new Result{pass=pass,before=mean[0],after=mean[1],litPixels=lit,condition="Camera and point light below fern; diagnostic cloned material culls all front faces, so only back-facing triangles contribute; fixed nonzero wind; no product material saved"},true));if(!pass)throw new Exception("backface response missing");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(output,"backface-error.txt"),e.ToString());EditorApplication.Exit(1);}}
}
